import json, copy
from pathlib import Path
from datetime import datetime
P=Path(__file__).resolve().parents[2]; C=P/'canon'
R=json.loads((C/'_build/initial_candidates.json').read_text('utf-8'))
E={x['id']:x for x in json.loads((P/'audit/evidence_records.json').read_text('utf-8-sig'))}
changes=[]
def edit(n,why,**values):
    x=R[n-1];old={k:copy.deepcopy(x.get(k)) for k in values}
    x.update(values);changes.append(dict(event=x['id'],before=old,after=values,reason=why))
def add(base,title,occ,state,refs=None,ranges=None,time=None,layer=None,tier=None,actors=None,knowledge=None,relationships=None,note='',before=None):
    x=copy.deepcopy(R[base-1]);x['id']=f'EV{len(R)+1:04d}';x['title']=title
    x.update(occurrence=occ,changes=state,direct_result=state,before=before or '见所列关联前置事件；本节点只记录下列独立变化。',knowledge=knowledge or [],relationships=relationships or [],note=note,related_events=[f'EV{base:04d}'])
    if refs is not None:x['audit_navigation']=refs.split(',') if refs else []
    if ranges is not None:x['source_ranges']=ranges
    elif refs is not None:x['source_ranges']=[[E[z]['start'],E[z]['end']] for z in x['audit_navigation']]
    if time:x['time']=time
    if layer:x['time_layer']=layer
    if tier:x['time_tier']=tier
    if actors:x['participants']=actors.split('、')
    R.append(x);changes.append(dict(event=x['id'],reason='按独立状态变化新增；从相应候选条目拆出或补足。',source_event=f'EV{base:04d}'))
    return len(R)

