# 完成核心状态字段，并将泛称拆为可查询的角色显示名。
for x in R:
    x['source_ranges']=sorted(set(map(tuple,x['source_ranges'])))
    x['revealed_at']=x['source_ranges']
    x['location']='见发生内容及原文定位；未点明的具体房间/坐标UNKNOWN。'
    x['claim_scope']='事件中直接呈现的行动及结果按A/CONFIRMED；说法、判断、评价、未兑现计划按下列限制单独读取。'
    x['qualified_claims']=[]
    if any(k in x['occurrence']+x['note'] for k in ['自述','说法','解释','口述','口供','猜','推','声称','称','宣告']):
        x['qualified_claims'].append({'grade':'D/C','status':'CHARACTER_BELIEF/INFERRED','scope':'人物话语的内容与由局部现象作出的推断','limit':x['note']})
    if '未知' in x['note'] or 'UNKNOWN' in x['note'] or x['id']=='EV0158':
        x['qualified_claims'].append({'grade':'F','status':'UNKNOWN','scope':'备注所列未决项，不补成已发生事件'})
    if x.get('time_status')=='DISPUTED':x['qualified_claims'].append({'grade':'F','status':'DISPUTED','scope':x['time']})
    for k in x['knowledge']:
        if k[3]=='CHARACTER_BELIEF':k[3]='BELIEVED'
    x['witnesses']='现场直接参加各自行动者：'+ '、'.join(x['participants'])+'。仅限其直接经历部分；不含不在场的回忆/转述过程。'
    x['later_informed']='；'.join(k[0]+'通过'+k[4]+'获“'+k[1]+'”' for k in x['knowledge'] if k[0]!='读者') or '本节点未明确新的事后转述者；后续传播见关联事件。'
    x['meaningfully_unaware']='未明示的不知情不作全称判断；具体保密/误解边见知识TEMP与备注。'
    x['long_term']='后续状态节点见关联事件；没有在原文中落定的后果保持UNKNOWN。'

(C/'events/records.json').write_text(json.dumps(R,ensure_ascii=False,indent=2),'utf-8')
